  function typeKey(plant) { return String(plant.generationType || plant.primaryFuel || plant.fuel || '').toLowerCase(); }
  function norm(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
  function keyFor(plant) { return [norm(plant.name), norm(plant.country), typeKey(plant)].join('|'); }
  const existing = window.GLOBALDATA_INFRASTRUCTURE?.powerPlants || [];
  const seen = new Set(existing.map(keyFor));
  const additions = plants.filter(plant => { const key = keyFor(plant); if (seen.has(key)) return false; seen.add(key); return true; });
  window.GLOBALDATA_NORTH_AMERICA_POWER = plants;
  if (window.GLOBALDATA_INFRASTRUCTURE) {
    window.GLOBALDATA_INFRASTRUCTURE.powerPlants = additions.concat(existing);
  }
